if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/course/lib.php');
try {
    global $DB, $USER, $CFG;
    $USER = get_admin();

    // Configure custom TinyMCE style formats (a JSON array merged into style_formats).
    // Inline styles are used so the formats render visibly without extra CSS.
    $styles = json_encode([
        ['title' => 'Notice', 'block' => 'div',
            'styles' => ['border-left' => '4px solid #e67e22', 'background' => '#fef5e7',
                'padding' => '10px 14px', 'margin' => '10px 0']],
        ['title' => 'Box', 'block' => 'div',
            'styles' => ['border' => '1px solid #c0c0c0', 'border-radius' => '6px',
                'padding' => '12px', 'margin' => '10px 0']],
        ['title' => 'Highlight', 'inline' => 'span',
            'styles' => ['background' => '#fff3cd', 'padding' => '1px 5px', 'border-radius' => '3px']],
        ['title' => 'Quote', 'block' => 'blockquote',
            'styles' => ['border-left' => '4px solid #3498db', 'color' => '#555',
                'font-style' => 'italic', 'padding' => '6px 0 6px 14px', 'margin' => '10px 0']],
    ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    set_config('json', $styles, 'tiny_customstyleformats');

    // Create the demo category and course from PHP so the setup is self-contained.
    $category = $DB->get_record('course_categories', ['name' => 'Demo Courses']);
    if (!$category) {
        $category = \core_course_category::create((object) ['name' => 'Demo Courses']);
    }
    $categoryid = is_object($category) ? $category->id : $category;

    $course = $DB->get_record('course', ['shortname' => 'tinystyles-demo']);
    if (!$course) {
        $course = create_course((object) [
            'fullname' => 'Custom Style Formats Demo',
            'shortname' => 'tinystyles-demo',
            'category' => $categoryid,
            'summary' => 'Demo course for the Tiny custom styles plugin. Open the Page below to see the custom Styles in the TinyMCE editor.',
            'summaryformat' => FORMAT_HTML,
        ]);
    }

    // Enrol the admin as editing teacher so the course shows up in "My courses".
    $manual = enrol_get_plugin('manual');
    $manualinstance = null;
    foreach (enrol_get_instances($course->id, false) as $inst) {
        if ($inst->enrol === 'manual') {
            $manualinstance = $inst;
            break;
        }
    }
    if (!$manualinstance && $manual) {
        $manualid = $manual->add_default_instance($course);
        $manualinstance = $manualid ? $DB->get_record('enrol', ['id' => $manualid]) : null;
    }
    $teacherrole = $DB->get_record('role', ['shortname' => 'editingteacher']);
    if ($manual && $manualinstance && $teacherrole) {
        $manual->enrol_user($manualinstance, $USER->id, $teacherrole->id);
    }

    // Add a Page activity whose content already uses the custom styles, so the
    // TinyMCE editor on its edit form shows both the styled content and the
    // custom "Styles" dropdown.
    $moduleid = $DB->get_field('modules', 'id', ['name' => 'page'], MUST_EXIST);
    if (!$DB->record_exists('page', ['course' => $course->id, 'name' => 'Custom style formats demo'])) {
        $content = '<h4>Custom style formats provided by tiny_customstyleformats</h4>'
            . '<p>Open the <strong>Styles</strong> dropdown in the editor toolbar above and apply any of '
            . 'these formats to your text:</p>'
            . '<div style="border-left:4px solid #e67e22;background:#fef5e7;padding:10px 14px;margin:10px 0">'
            . '<strong>Notice</strong> &ndash; a callout for important information.</div>'
            . '<div style="border:1px solid #c0c0c0;border-radius:6px;padding:12px;margin:10px 0">'
            . '<strong>Box</strong> &ndash; a bordered box.</div>'
            . '<p>Inline text can be <span style="background:#fff3cd;padding:1px 5px;border-radius:3px">'
            . 'Highlighted</span>.</p>'
            . '<blockquote style="border-left:4px solid #3498db;color:#555;font-style:italic;'
            . 'padding:6px 0 6px 14px;margin:10px 0">Quote &ndash; a styled quotation.</blockquote>';

        $pagerec = (object) [
            'course' => $course->id,
            'name' => 'Custom style formats demo',
            'intro' => '',
            'introformat' => FORMAT_HTML,
            'content' => $content,
            'contentformat' => FORMAT_HTML,
            'legacyfiles' => 0,
            'display' => 0,
            'displayoptions' => '',
            'revision' => 1,
            'timemodified' => time(),
        ];
        $pagerec->id = $DB->insert_record('page', $pagerec);

        $newcm = (object) [
            'course' => $course->id,
            'module' => $moduleid,
            'instance' => $pagerec->id,
            'section' => 0,
            'added' => time(),
            'visible' => 1,
            'visibleoncoursepage' => 1,
            'visibleold' => 1,
            'groupmode' => 0,
            'groupingid' => 0,
        ];
        $cmid = add_course_module($newcm);
        course_add_cm_to_section($course->id, $cmid, 0);
        rebuild_course_cache($course->id, true);
    }

    if (!$DB->record_exists('page', ['course' => $course->id, 'name' => 'Custom style formats demo'])) {
        throw new \RuntimeException('The demo Page activity is missing after provisioning.');
    }

    echo "Provisioned tiny_customstyleformats demo on course 'tinystyles-demo' with a Page using the custom styles.\n";
} catch (\Throwable $e) {
    fwrite(STDERR, 'tiny_customstyleformats demo provisioning failed: ' . $e->getMessage() . "\n");
}
